// --- artifacts --------------------------------------------------------------

std::vector<Row> doctor_artifacts() {
  const fs::path root = repo_root();
  struct A {
    const char* label;
    const char* env;
    fs::path def;
  };
  // Env overrides match hsim's _ARTIFACT_ENV so a test can simulate a missing
  // binary. Order (vsim, qemu, plugin) mirrors the golden's dict order.
  const A arts[] = {
      {"vsim", "VSIM_BIN", root / "verilator" / "build" / "sim_ax45mpv_premium"},
      {"qemu", "VSIM_QEMU", root / "build" / "qemu" / "qemu-system-riscv64"},
      {"plugin", "VSIM_PLUGIN", root / "qemu_plugin" / "libhybrid_handoff.so"},
