1	// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <cstdlib>
11	#include <exception>
12	#include <string>
13	#include <string_view>
14	
15	#include "cli.hpp"
16	#include "dev_mode.hpp"
17	#include "repo_root.hpp"
18	
19	namespace andes_sim {
20	int cmd_list(const Cli& cli);
21	}  // namespace andes_sim
22	
23	namespace {
24	
25	using andes_sim::Cli;
26	using andes_sim::is_dev_mode;
27	
28	// Known command names. list has a handler (dispatched in main); the rest are
29	// stable slots for unfinished features, kept here so `find` routes them to
30	// the "not yet implemented" stub rather than "unknown command", while never
31	// appearing in `--help` (print_usage renders only the list block, so the
32	// product never advertises half-built work). Developer build/test tooling
33	// lives in scripts/, not the binary. Display strings (briefs) live in the
34	// help model below.
35	struct Subcommand {
36	  std::string_view name;
37	};
38	
39	constexpr Subcommand kSubcommands[] = {
40	    {"list"},
41	    {"profile"},
42	    {"cluster"},
43	    {"estimate"},
44	};
45	
46	const Subcommand* find(std::string_view name) {
47	  for (const Subcommand& s : kSubcommands)
48	    if (s.name == name) return &s;
49	  return nullptr;
50	}
51	
52	// ---- help model: the user-facing surface rendered as a command tree --------
53	//
54	// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
55	// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
56	struct TargetRow {
57	  const char* name;
58	  const char* brief;
59	  bool dev;
60	};
61	constexpr TargetRow kListTargets[] = {
62	    {"models", "the modes and their engines", false},
63	    {"engines", "discovered cycle-accurate engines", false},
64	    {"fixtures", "internal test ELFs (developer target)", true},
65	};
66	
67	// A major command line at column 0: `name   brief`.
68	void print_major(std::FILE* out, const char* name, const char* brief) {
69	  std::fprintf(out, "%-7s %s\n", name, brief);
70	}
71	
72	// A subcommand/target line, indented two under its command: `  name   brief`.
73	void print_sub(std::FILE* out, const char* name, const char* brief) {
74	  std::fprintf(out, "  %-9s %s\n", name, brief);
75	}
76	
77	void print_list_block(std::FILE* out) {
78	  print_major(out, "list", "list what is available");
79	  for (const TargetRow& t : kListTargets) {
80	    if (t.dev && !is_dev_mode()) continue;
81	    print_sub(out, t.name, t.brief);
82	  }
83	}
84	
85	// Top-level `andesim --help`: the whole tree -- every major command and its
86	// subcommands, so one screen shows everything.
87	void print_usage(std::FILE* out) {
88	  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
89	             out);
90	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
91	             out);
92	  print_list_block(out);
93	  std::fputs("\n'andesim list --help' for per-command detail.\n", out);
94	}
95	
96	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
97	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
98	  if (sc.name == "list") { print_list_block(out); return; }
99	  // A Hidden/unfinished command: a stable usage line, no advertised detail.
100	  std::fprintf(out, "usage: andesim %.*s [args...]\n",
101	               static_cast<int>(sc.name.size()), sc.name.data());
102	}
103	
104	}  // namespace
105	
106	int main(int argc, char** argv) {
107	  using namespace andes_sim;
108	
109	  Cli cli = parse_cli(argc, argv);
110	  if (!cli.error.empty()) {
111	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
112	    return 2;
113	  }
114	
115	  if (cli.subcommand.empty()) {  // no command, or top-level -h
116	    if (cli.help) {
117	      print_usage(stdout);
118	      return 0;
119	    }
120	    print_usage(stderr);
121	    return 2;
122	  }
123	
124	  const Subcommand* sc = find(cli.subcommand);
125	  if (!sc) {
126	    std::fprintf(stderr, "andesim: unknown command '%s'\n\n",
127	                 cli.subcommand.c_str());
128	    print_usage(stderr);
129	    return 2;
130	  }
131	
132	  if (cli.help) {
133	    print_subcommand_help(*sc, stdout);
134	    return 0;
135	  }
136	
137	  if (cli.subcommand == "list") return cmd_list(cli);
138	
139	  // Remaining subcommands stub out until their feature lands. Resolve the repo
140	  // root so the discovery path stays live and observable.
141	  std::string root;
142	  try {
143	    root = repo_root().string();
144	  } catch (const std::exception& e) {
145	    root = std::string("<unknown: ") + e.what() + ">";
146	  }
147	  std::fprintf(stderr, "andesim %s: not yet implemented (repo root: %s)\n",
148	               cli.subcommand.c_str(), root.c_str());
149	  return 3;
150	}
